CREATE TABLE ALUMNOS(
    ID_MATRICULA NUMBER,
    NOMBRE NVARCHAR2(100),
    APP NVARCHAR2(100),
    EDAD NUMBER,
    SEXO NVARCHAR2(100),
    CONSTRAINT PK_ALUMNOS PRIMARY KEY (ID_MATRICULA)
);
--DINSERTA REGISTROS









COMMIT;
--BUSQUEDA DE DATOS DE UNA COLUMNA QUE COMIENZEN POR UNA LETRA 
SELECT * FROM ALUMNOS;
--Revisado 30/09/2026 Luis Alberto Luna Hernandez
-
--ORDEBAMIENTO DE FORMA DESC NOMBRE, UNIVERSIDAD Y CARRERA 
SELECT NOMBRE, UNIVERSIDAD, CARRERA FROM ALUMNOS
ORDER BY NOMBRE DESC, UNIVERSIDAD DESC, CARRERA DESC;
--ORDENAMIENTO DE FORMA ASC NOMBRE, UNIVERSIDAD, CARRERA
SELECT NOMBRE, UNIVERSIDAD, CARRERA FROM ALUMNOS
ORDER BY NOMBRE ASC, UNIVERSIDAD ASC, CARRERA ASC;


--ALTER TABLE ALUMNOS ADD ESPECIALIDAD NVARCHAR2(50);ALTER TABLE ALUMNOS ADD CARRERA NVARCHAR2(50);

DELETE FROM ALUMNOS;

SELECT * FROM ALUMNOS WHERE APELLIDO LIKE 'H%';
--BUSQUEDA DE DATOS DE UNA COLUMNA QUE TERMINE POR UNA LETRA O NUMERO
SELECT * FROM ALUMNOS WHERE UNIVERSIDAD LIKE '%A'
--BUSQUEDA DE DATOS DE UNA COLUMNA QUE CONTENGA POR UNA LETRA O NUMERO
SELECT * FROM ALUMNOS WHERE NOMBRE LIKE '%S'